/// <summary>
///     The <c>AVASalesCopyingFrm_CustInvoiceJourDS_Extension</c> class is the extension for <c>SalesCopying</c>
/// </summary>
[ExtensionOf(formDataSourceStr(SalesCopying, CustInvoiceJour))]
final class AVASalesCopyingFrm_CustInvoiceJourDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
void init()
{
    QueryBuildDataSource    locQBDS;
    QueryBuildRange         locQBR;

    next init();

    if(     element.avaSalesOrderCreditNoteSingle
        &&  element.avaSalesOrderCreditNoteSingleSalesId    )
    {
        locQBDS = this.queryBuildDataSource();
        locQBR  = SysQuery::findOrCreateRange(locQBDS, fieldNum(CustInvoiceJour, SalesId));
        locQBR.value(SysQuery::value(element.avaSalesOrderCreditNoteSingleSalesId));
    }
}
